import { BEAMS_COMPOSITE, BEAMS_FIELD, BEAMS_VERTEX } from './beams-shaders';
import type {
  BeamsEngine,
  BeamsLook,
  BeamsPresetName,
  BeamsProps,
  BeamsSettings,
} from './types';

type Vec3 = [number, number, number];
type Uniforms = Map<string, WebGLUniformLocation | null>;

const INTRO_SECONDS = 1.6;
const MAX_FIELD_PIXELS = 1600000;

const LOOK: BeamsLook = {
  color: '#ffffff',
  beamWidth: 140,
  rotation: 30,
  waveLength: 233,
  depth: 1,
  sharpness: 0.6,
  twist: 0,
  fillLight: 0.3,
  glow: 0.6,
};

const PRESETS: Record<BeamsPresetName, Partial<BeamsLook>> = {
  studio: {},
  ember: { color: '#ff8a4c', rotation: 20, glow: 0.85, fillLight: 0.2 },
  glacier: {
    color: '#8fd0ff',
    beamWidth: 90,
    rotation: 45,
    sharpness: 0.75,
    fillLight: 0.4,
  },
  chrome: {
    sharpness: 0.8,
    depth: 1.2,
    fillLight: 0.9,
    glow: 0.4,
    rotation: 35,
  },
  dawn: {
    color: '#ffd59a',
    rotation: -30,
    waveLength: 320,
    twist: 0.4,
    glow: 0.7,
  },
};

/** Full look for a named preset, ready to spread onto the component. */
export function beamsPreset(name: BeamsPresetName): BeamsLook {
  return { ...LOOK, ...PRESETS[name] };
}

export function isBeamsPreset(value: unknown): value is BeamsPresetName {
  return typeof value === 'string' && Object.hasOwn(PRESETS, value);
}

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

export function normalizeBeams(
  props: BeamsProps,
  reduce: boolean,
): BeamsSettings {
  return {
    color: String(props.color ?? '#ffffff'),
    beamWidth: Math.max(8, props.beamWidth ?? 140),
    rotation: props.rotation ?? 30,
    speed: props.speed ?? 1,
    waveLength: Math.max(20, props.waveLength ?? 233),
    depth: Math.max(0, props.depth ?? 1),
    sharpness: clamp(props.sharpness ?? 0.6, 0, 1),
    twist: clamp(props.twist ?? 0, 0, 2),
    fillLight: clamp(props.fillLight ?? 0.3, 0, 1.5),
    glow: Math.max(0, props.glow ?? 0.6),
    brightness: Math.max(0, props.brightness ?? 1.6),
    variation: Number(props.variation) || 0,
    grain: Math.max(0, props.grain ?? 0.35),
    quality: clamp(props.quality ?? 0.75, 0.25, 1),
    mouseInteraction: props.mouseInteraction ?? true,
    mouseStrength: Math.max(0, props.mouseStrength ?? 1),
    intro: props.intro ?? true,
    fade: clamp(props.fade ?? 0, 0, 1),
    opacity: clamp(props.opacity ?? 1, 0, 1),
    lightMode: props.lightMode ?? false,
    paused: props.paused ?? false,
    dpr: props.dpr,
    reduce,
  };
}

function compile(gl: WebGL2RenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
  gl.deleteShader(shader);
  return null;
}

function link(gl: WebGL2RenderingContext, fragmentSource: string) {
  const vertex = compile(gl, gl.VERTEX_SHADER, BEAMS_VERTEX);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, fragmentSource);
  const program = gl.createProgram();
  if (!vertex || !fragment || !program) return null;
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.bindAttribLocation(program, 0, 'aPosition');
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return null;
  }
  const uniforms: Uniforms = new Map();
  const count: number = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
  for (let i = 0; i < count; i++) {
    const info = gl.getActiveUniform(program, i);
    if (info)
      uniforms.set(info.name, gl.getUniformLocation(program, info.name));
  }
  return { program, uniforms };
}

export function createBeams(
  container: HTMLElement,
  canvas: HTMLCanvasElement,
  getSettings: () => BeamsSettings,
): BeamsEngine | null {
  const gl = canvas.getContext('webgl2', {
    alpha: true,
    premultipliedAlpha: true,
    antialias: false,
    depth: false,
    stencil: false,
    powerPreference: 'high-performance',
  });
  if (!gl) return null;

  const floatTargets = !!gl.getExtension('EXT_color_buffer_float');
  const fieldProgram = link(gl, BEAMS_FIELD);
  const compositeProgram = link(gl, BEAMS_COMPOSITE);
  if (!fieldProgram || !compositeProgram) return null;
  const f = (name: string) => fieldProgram.uniforms.get(name) ?? null;
  const c = (name: string) => compositeProgram.uniforms.get(name) ?? null;

  const buffer = gl.createBuffer();
  const vao = gl.createVertexArray();
  gl.bindVertexArray(vao);
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 3, -1, -1, 3]),
    gl.STATIC_DRAW,
  );
  gl.enableVertexAttribArray(0);
  gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

  let texture: WebGLTexture | null = null;
  const framebuffer = gl.createFramebuffer();
  const target = { width: 0, height: 0 };
  const sizeTarget = (width: number, height: number) => {
    if (target.width === width && target.height === height) return;
    target.width = width;
    target.height = height;
    if (texture) gl.deleteTexture(texture);
    texture = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, texture);
    const levels = Math.floor(Math.log2(Math.max(width, height))) + 1;
    gl.texStorage2D(
      gl.TEXTURE_2D,
      levels,
      floatTargets ? gl.RGBA16F : gl.RGBA8,
      width,
      height,
    );
    gl.texParameteri(
      gl.TEXTURE_2D,
      gl.TEXTURE_MIN_FILTER,
      gl.LINEAR_MIPMAP_LINEAR,
    );
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
    gl.framebufferTexture2D(
      gl.FRAMEBUFFER,
      gl.COLOR_ATTACHMENT0,
      gl.TEXTURE_2D,
      texture,
      0,
    );
  };

  const probe = document
    .createElement('canvas')
    .getContext('2d', { willReadFrequently: true });
  const colorCache = new Map<string, Vec3>();
  const toLinear = (value: string): Vec3 => {
    const cached = colorCache.get(value);
    if (cached) return cached;
    let rgb: Vec3 = [1, 1, 1];
    if (probe) {
      probe.clearRect(0, 0, 1, 1);
      probe.fillStyle = '#ffffff';
      probe.fillStyle = value;
      probe.fillRect(0, 0, 1, 1);
      const data = probe.getImageData(0, 0, 1, 1).data;
      rgb = [
        Math.pow((data[0] ?? 255) / 255, 2.2),
        Math.pow((data[1] ?? 255) / 255, 2.2),
        Math.pow((data[2] ?? 255) / 255, 2.2),
      ];
    }
    colorCache.set(value, rgb);
    return rgb;
  };

  const initial = getSettings();
  const view = { width: 1, height: 1, fieldWidth: 1, fieldHeight: 1 };
  const pointer = { x: 0, y: 0, inside: false };
  const state = {
    clock: 0,
    intro: initial.intro && !initial.reduce ? 0 : 1,
    reach: 0,
    x: 0,
    y: 0,
    lightY: 0,
  };
  let raf = 0;
  let last = 0;
  let visible = true;
  let disposed = false;
  let lastQuality = initial.quality;
  let lastDpr = initial.dpr;

  const render = () => {
    const s = getSettings();
    const p = state.intro;
    const presence = p * p * p * (p * (p * 6 - 15) + 10);
    gl.bindVertexArray(vao);
    sizeTarget(view.fieldWidth, view.fieldHeight);

    const angle = (s.rotation * Math.PI) / 180;
    const sweep = (1 - presence) * -9;
    const reach = state.reach * s.mouseStrength;
    gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
    gl.viewport(0, 0, target.width, target.height);
    gl.useProgram(fieldProgram.program);
    gl.uniform2f(f('uView'), view.width, view.height);
    gl.uniform2f(
      f('uScale'),
      view.width / target.width,
      view.height / target.height,
    );
    gl.uniform2f(f('uTurn'), Math.cos(angle), Math.sin(angle));
    gl.uniform1f(f('uTime'), (state.clock * 0.12) % 289);
    gl.uniform1f(f('uWidth'), s.beamWidth);
    gl.uniform1f(f('uWave'), s.waveLength);
    gl.uniform1f(f('uDepth'), s.depth);
    gl.uniform1f(f('uRough'), 0.55 - s.sharpness * 0.5);
    gl.uniform1f(f('uSeed'), s.variation);
    gl.uniform1f(f('uTwist'), s.twist);
    gl.uniform1f(f('uFill'), s.fillLight);
    gl.uniform3f(f('uLight'), 0, 3 + sweep + state.lightY * reach, 10);
    gl.uniform1f(f('uCamera'), view.height * 1.866);
    gl.uniform4f(
      f('uPointer'),
      state.x,
      view.height - state.y,
      reach,
      Math.max(view.height, view.width) * 0.28,
    );
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.generateMipmap(gl.TEXTURE_2D);

    const tint = toLinear(s.color);
    const tone = 0.2126 * tint[0] + 0.7152 * tint[1] + 0.0722 * tint[2];
    const shadeDepth = Math.min(1, 0.18 / Math.max(tone, 0.001));
    const ink = tint.map((v) => Math.pow(Math.min(1, v * shadeDepth), 1 / 2.2));
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.useProgram(compositeProgram.program);
    gl.uniform2f(c('uResolution'), canvas.width, canvas.height);
    gl.uniform3fv(c('uColor'), tint);
    gl.uniform3fv(c('uInk'), ink);
    gl.uniform1f(c('uGain'), s.brightness);
    gl.uniform1f(c('uGlow'), s.glow);
    gl.uniform1f(c('uPresence'), presence);
    gl.uniform1f(c('uGrain'), s.grain * 1.75);
    gl.uniform1f(c('uFade'), s.fade);
    gl.uniform1f(c('uOpacity'), s.opacity);
    gl.uniform1f(c('uLightMode'), s.lightMode ? 1 : 0);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.uniform1i(c('uField'), 0);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  };

  const frame = (now: number) => {
    raf = 0;
    if (disposed || !visible || document.hidden) return;
    const s = getSettings();
    const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
    last = now;
    const moving = !s.paused && !s.reduce;
    if (moving) state.clock += dt * s.speed;
    if (!s.intro || s.reduce) state.intro = 1;
    else if (state.intro < 1) {
      state.intro = Math.min(1, state.intro + dt / INTRO_SECONDS);
    }

    const engaged = s.mouseInteraction && pointer.inside && !s.reduce;
    if (engaged && state.reach < 0.01) {
      state.x = pointer.x;
      state.y = pointer.y;
    }
    const follow = 1 - Math.exp(-dt * 7);
    state.x += (pointer.x - state.x) * follow;
    state.y += (pointer.y - state.y) * follow;
    state.reach +=
      ((engaged ? 1 : 0) - state.reach) *
      (1 - Math.exp(-dt * (engaged ? 3.2 : 1.8)));
    const turn = (s.rotation * Math.PI) / 180;
    const offsetX = state.x - view.width / 2;
    const offsetY = view.height / 2 - state.y;
    const along = -Math.sin(turn) * offsetX + Math.cos(turn) * offsetY;
    state.lightY = clamp((along / (view.height * 0.5)) * 3, -4, 4);
    render();

    const settling =
      state.intro < 1 ||
      Math.abs((engaged ? 1 : 0) - state.reach) > 0.002 ||
      Math.abs(pointer.x - state.x) + Math.abs(pointer.y - state.y) > 0.3;
    if (moving || settling) raf = requestAnimationFrame(frame);
    else last = 0;
  };

  const wake = () => {
    if (!raf && !disposed && visible && !document.hidden) {
      raf = requestAnimationFrame(frame);
    }
  };

  const resize = () => {
    if (disposed) return;
    const s = getSettings();
    const width = Math.max(1, container.clientWidth);
    const height = Math.max(1, container.clientHeight);
    const ratio = Math.min(s.dpr || window.devicePixelRatio || 1, 2);
    view.width = width;
    view.height = height;
    canvas.width = Math.max(1, Math.round(width * ratio));
    canvas.height = Math.max(1, Math.round(height * ratio));
    let fieldScale = s.quality * ratio;
    if (width * height * fieldScale * fieldScale > MAX_FIELD_PIXELS) {
      fieldScale = Math.sqrt(MAX_FIELD_PIXELS / (width * height));
    }
    view.fieldWidth = Math.max(1, Math.round(width * fieldScale));
    view.fieldHeight = Math.max(1, Math.round(height * fieldScale));
    if (!raf) render();
    wake();
  };

  resize();

  return {
    resize,
    refresh() {
      if (disposed) return;
      const s = getSettings();
      if (s.quality !== lastQuality || s.dpr !== lastDpr) {
        lastQuality = s.quality;
        lastDpr = s.dpr;
        resize();
        return;
      }
      if (!raf) render();
      wake();
    },
    setVisible(nextVisible: boolean) {
      visible = nextVisible;
      if (visible) {
        last = 0;
        wake();
      }
    },
    visibilityChange() {
      last = 0;
      wake();
    },
    pointerMove(event: PointerEvent) {
      const rect = container.getBoundingClientRect();
      pointer.x = event.clientX - rect.left;
      pointer.y = event.clientY - rect.top;
      pointer.inside =
        pointer.x >= 0 &&
        pointer.y >= 0 &&
        pointer.x <= rect.width &&
        pointer.y <= rect.height;
      wake();
    },
    pointerOut(event: PointerEvent) {
      if (event.relatedTarget) return;
      pointer.inside = false;
      wake();
    },
    destroy() {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      if (texture) gl.deleteTexture(texture);
      gl.deleteFramebuffer(framebuffer);
      gl.deleteProgram(fieldProgram.program);
      gl.deleteProgram(compositeProgram.program);
      gl.deleteBuffer(buffer);
      gl.deleteVertexArray(vao);
      gl.getExtension('WEBGL_lose_context')?.loseContext();
    },
  };
}

export const BEAMS_VERTEX = `#version 300 es
in vec2 aPosition;
void main() {
  gl_Position = vec4(aPosition, 0.0, 1.0);
}`;

export const BEAMS_FIELD = `#version 300 es
precision highp float;
uniform vec2 uView;
uniform vec2 uScale;
uniform vec2 uTurn;
uniform float uTime;
uniform float uWidth;
uniform float uWave;
uniform float uDepth;
uniform float uRough;
uniform float uSeed;
uniform float uTwist;
uniform vec3 uLight;
uniform float uFill;
uniform float uCamera;
uniform vec4 uPointer;
out vec4 outColor;

const float PI = 3.141592653589793;

vec4 permute(vec4 x) {
  return mod(((x * 34.0) + 1.0) * x, 289.0);
}

vec4 taylorInvSqrt(vec4 r) {
  return 1.79284291400159 - 0.85373472095314 * r;
}

vec3 fade(vec3 t) {
  return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

float cnoise(vec3 P) {
  vec3 Pi0 = floor(P);
  vec3 Pi1 = Pi0 + vec3(1.0);
  Pi0 = mod(Pi0, 289.0);
  Pi1 = mod(Pi1, 289.0);
  vec3 Pf0 = fract(P);
  vec3 Pf1 = Pf0 - vec3(1.0);
  vec4 ix = vec4(Pi0.x, Pi1.x, Pi0.x, Pi1.x);
  vec4 iy = vec4(Pi0.yy, Pi1.yy);
  vec4 iz0 = Pi0.zzzz;
  vec4 iz1 = Pi1.zzzz;
  vec4 ixy = permute(permute(ix) + iy);
  vec4 ixy0 = permute(ixy + iz0);
  vec4 ixy1 = permute(ixy + iz1);
  vec4 gx0 = ixy0 / 7.0;
  vec4 gy0 = fract(floor(gx0) / 7.0) - 0.5;
  gx0 = fract(gx0);
  vec4 gz0 = vec4(0.5) - abs(gx0) - abs(gy0);
  vec4 sz0 = step(gz0, vec4(0.0));
  gx0 -= sz0 * (step(0.0, gx0) - 0.5);
  gy0 -= sz0 * (step(0.0, gy0) - 0.5);
  vec4 gx1 = ixy1 / 7.0;
  vec4 gy1 = fract(floor(gx1) / 7.0) - 0.5;
  gx1 = fract(gx1);
  vec4 gz1 = vec4(0.5) - abs(gx1) - abs(gy1);
  vec4 sz1 = step(gz1, vec4(0.0));
  gx1 -= sz1 * (step(0.0, gx1) - 0.5);
  gy1 -= sz1 * (step(0.0, gy1) - 0.5);
  vec3 g000 = vec3(gx0.x, gy0.x, gz0.x);
  vec3 g100 = vec3(gx0.y, gy0.y, gz0.y);
  vec3 g010 = vec3(gx0.z, gy0.z, gz0.z);
  vec3 g110 = vec3(gx0.w, gy0.w, gz0.w);
  vec3 g001 = vec3(gx1.x, gy1.x, gz1.x);
  vec3 g101 = vec3(gx1.y, gy1.y, gz1.y);
  vec3 g011 = vec3(gx1.z, gy1.z, gz1.z);
  vec3 g111 = vec3(gx1.w, gy1.w, gz1.w);
  vec4 norm0 = taylorInvSqrt(vec4(dot(g000, g000), dot(g010, g010), dot(g100, g100), dot(g110, g110)));
  g000 *= norm0.x;
  g010 *= norm0.y;
  g100 *= norm0.z;
  g110 *= norm0.w;
  vec4 norm1 = taylorInvSqrt(vec4(dot(g001, g001), dot(g011, g011), dot(g101, g101), dot(g111, g111)));
  g001 *= norm1.x;
  g011 *= norm1.y;
  g101 *= norm1.z;
  g111 *= norm1.w;
  float n000 = dot(g000, Pf0);
  float n100 = dot(g100, vec3(Pf1.x, Pf0.yz));
  float n010 = dot(g010, vec3(Pf0.x, Pf1.y, Pf0.z));
  float n110 = dot(g110, vec3(Pf1.xy, Pf0.z));
  float n001 = dot(g001, vec3(Pf0.xy, Pf1.z));
  float n101 = dot(g101, vec3(Pf1.x, Pf0.y, Pf1.z));
  float n011 = dot(g011, vec3(Pf0.x, Pf1.yz));
  float n111 = dot(g111, Pf1);
  vec3 fade_xyz = fade(Pf0);
  vec4 n_z = mix(vec4(n000, n100, n010, n110), vec4(n001, n101, n011, n111), fade_xyz.z);
  vec2 n_yz = mix(n_z.xy, n_z.zw, fade_xyz.y);
  float n_xyz = mix(n_yz.x, n_yz.y, fade_xyz.x);
  return 2.2 * n_xyz;
}

float laneHash(float lane) {
  return fract(sin(lane * 91.3458 + uSeed * 17.17) * 47453.5453);
}

float lobe(float nh, float nl, float nv, float vh, float roughness) {
  float a = roughness * roughness;
  float a2 = a * a;
  float d = nh * nh * (a2 - 1.0) + 1.0;
  float distribution = a2 / (PI * d * d);
  float gv = nl * sqrt(nv * nv * (1.0 - a2) + a2);
  float gl = nv * sqrt(nl * nl * (1.0 - a2) + a2);
  float visibility = 0.5 / max(gv + gl, 0.0001);
  float fresnel = 0.028 + 0.972 * pow(1.0 - vh, 5.0);
  return distribution * visibility * fresnel * nl;
}

vec2 glint(float lane, vec2 local) {
  float along = local.y / uWave - laneHash(lane) * 60.0;
  float step = 0.01;
  float slope = (cnoise(vec3(0.0, along + step, uTime)) - cnoise(vec3(0.0, along - step, uTime))) / (2.0 * step);
  slope *= 0.2 * uDepth;
  float spin = laneHash(lane + 0.37);
  float tilt = ((spin - 0.5) * 0.5 + sin(uTime * 2.1 + spin * 6.2831) * 0.06) * uTwist;
  vec3 normal = normalize(vec3(tilt, -slope, 1.0));
  vec3 view = normalize(vec3(-local, uCamera));
  float nv = max(dot(normal, view), 0.0001);
  vec3 light = normalize(uLight);
  vec3 halfway = normalize(light + view);
  float core = lobe(max(dot(normal, halfway), 0.0), max(dot(normal, light), 0.0), nv, max(dot(view, halfway), 0.0), uRough);
  vec3 fill = normalize(vec3(0.0, -uLight.y * 1.25, uLight.z));
  vec3 fillHalf = normalize(fill + view);
  core += uFill * lobe(max(dot(normal, fillHalf), 0.0), max(dot(normal, fill), 0.0), nv, max(dot(view, fillHalf), 0.0), uRough);
  return vec2(core, core);
}

void main() {
  vec2 css = gl_FragCoord.xy * uScale;
  vec2 centered = css - uView * 0.5;
  vec2 local = mat2(uTurn.x, -uTurn.y, uTurn.y, uTurn.x) * centered;

  float across = local.x / uWidth + 0.5;
  float lane = floor(across);
  float u = across - lane;
  vec2 value = glint(lane, local);

  float pixel = max(uScale.x, uScale.y);
  float seam = min(u, 1.0 - u) * uWidth;
  if (seam < pixel * 1.5) {
    float other = u < 0.5 ? lane - 1.0 : lane + 1.0;
    float blend = 0.5 * (1.0 - smoothstep(0.0, pixel * 1.5, seam));
    value = mix(value, glint(other, local), blend);
  }

  vec2 toPointer = css - uPointer.xy;
  float near = exp(-dot(toPointer, toPointer) / (2.0 * uPointer.w * uPointer.w)) * uPointer.z;
  value *= 1.0 + near * 0.8;
  float hot = max(value.y - 0.18, 0.0);
  outColor = vec4(value.x, value.y, min(hot, 6.0), 1.0);
}`;

export const BEAMS_COMPOSITE = `#version 300 es
precision highp float;
uniform sampler2D uField;
uniform vec2 uResolution;
uniform vec3 uColor;
uniform vec3 uInk;
uniform float uGain;
uniform float uGlow;
uniform float uPresence;
uniform float uGrain;
uniform float uFade;
uniform float uOpacity;
uniform float uLightMode;
out vec4 outColor;

float random(vec2 st) {
  return fract(sin(dot(st, vec2(12.9898, 78.233))) * 43758.5453123);
}

float grainNoise(vec2 st) {
  vec2 i = floor(st);
  vec2 f = fract(st);
  float a = random(i);
  float b = random(i + vec2(1.0, 0.0));
  float c = random(i + vec2(0.0, 1.0));
  float d = random(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

vec3 acesFilmic(vec3 color) {
  const mat3 inputMatrix = mat3(
    vec3(0.59719, 0.07600, 0.02840),
    vec3(0.35458, 0.90834, 0.13383),
    vec3(0.04823, 0.01566, 0.83777)
  );
  const mat3 outputMatrix = mat3(
    vec3(1.60475, -0.10208, -0.00327),
    vec3(-0.53108, 1.10813, -0.07276),
    vec3(-0.07367, -0.00605, 1.07602)
  );
  color = inputMatrix * (color / 0.6);
  vec3 a = color * (color + 0.0245786) - 0.000090537;
  vec3 b = color * (0.983729 * color + 0.4329510) + 0.238081;
  color = outputMatrix * (a / b);
  return clamp(color, 0.0, 1.0);
}

vec3 toSrgb(vec3 color) {
  return mix(color * 12.92, 1.055 * pow(color, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), color));
}

float feather(float x, float edge) {
  float t = clamp(x / max(edge, 0.0001), 0.0, 1.0);
  return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

void main() {
  vec2 uv = gl_FragCoord.xy / uResolution;
  float radiance = textureLod(uField, uv, 0.0).r;
  float bloom = 0.0;
  bloom += textureLod(uField, uv, 2.0).b * 0.3;
  bloom += textureLod(uField, uv, 3.0).b * 0.3;
  bloom += textureLod(uField, uv, 4.0).b * 0.22;
  bloom += textureLod(uField, uv, 5.0).b * 0.18;

  float hot = textureLod(uField, uv, 0.0).g;
  vec3 light = uColor * (radiance + bloom * uGlow) * uGain;
  light += mix(uColor, vec3(1.0), 0.7) * hot * hot * 0.12 * uGain;
  light *= uPresence;
  vec3 color = toSrgb(acesFilmic(light));
  color -= grainNoise(gl_FragCoord.xy) / 15.0 * uGrain;
  color = max(color, 0.0);

  float edge = uFade * 0.5;
  float mask = feather(uv.x, edge) * feather(1.0 - uv.x, edge) * feather(uv.y, edge) * feather(1.0 - uv.y, edge);
  mask *= uOpacity;
  float dither = (random(gl_FragCoord.yx + 31.7) - 0.5) / 255.0;

  float peak = max(color.r, max(color.g, color.b));
  if (uLightMode > 0.5) {
    float alpha = clamp(peak * 0.9 + dither, 0.0, 1.0) * mask;
    outColor = vec4(uInk * alpha, alpha);
  } else {
    color = clamp(color + dither, 0.0, 1.0) * mask;
    outColor = vec4(color, max(color.r, max(color.g, color.b)));
  }
}`;

export { default as Beams } from './Beams.vue';
export { beamsPreset, isBeamsPreset } from './beams-gl';
export type { BeamsLook, BeamsPresetName, BeamsProps } from './types';

export interface BeamsProps {
  /** Color of the light that glints off the beams. */
  color?: string;
  /** Width of each beam, in px. */
  beamWidth?: number;
  /** Angle of the beams, in degrees. */
  rotation?: number;
  /** How fast the ripples move. */
  speed?: number;
  /** Length of the ripples along each beam, in px. */
  waveLength?: number;
  /** How deep the ripples are. Deeper ripples catch the light in more places. */
  depth?: number;
  /** How crisp the glints are, from 0 for soft satin to 1 for sharp, glossy streaks. */
  sharpness?: number;
  /** Turns each beam slightly on its own axis, so glints show up on more beams. */
  twist?: number;
  /** Strength of a dimmer second light from the other side. */
  fillLight?: number;
  /** Soft glow around the brightest glints. */
  glow?: number;
  /** Strength of the light. */
  brightness?: number;
  /** Picks a different ripple pattern. Any number works. */
  variation?: number;
  /** Strength of the film grain, from 0 to 1. */
  grain?: number;
  /** Render resolution, from 0.25 to 1. Lower values run faster. */
  quality?: number;
  /** The cursor moves the light along the beams and brightens the glints near it. */
  mouseInteraction?: boolean;
  /** How strongly the cursor moves the light. */
  mouseStrength?: number;
  /** Sweeps the light in on mount. */
  intro?: boolean;
  /** Fades the edges into the page, from 0 to 1. */
  fade?: number;
  /** Opacity of the whole effect. */
  opacity?: number;
  /** Prints the glints as soft ink, for light backgrounds. */
  lightMode?: boolean;
  /** Optional solid background. By default the canvas is transparent. */
  backgroundColor?: string;
  /** Freezes the animation. */
  paused?: boolean;
  /** Maximum device pixel ratio, capped at 2. */
  dpr?: number;
  /** Extra classes for the container. */
  class?: string;
}

export interface BeamsSettings {
  color: string;
  beamWidth: number;
  rotation: number;
  speed: number;
  waveLength: number;
  depth: number;
  sharpness: number;
  twist: number;
  fillLight: number;
  glow: number;
  brightness: number;
  variation: number;
  grain: number;
  quality: number;
  mouseInteraction: boolean;
  mouseStrength: number;
  intro: boolean;
  fade: number;
  opacity: number;
  lightMode: boolean;
  paused: boolean;
  dpr: number | undefined;
  reduce: boolean;
}

export type BeamsPresetName =
  | 'studio'
  | 'ember'
  | 'glacier'
  | 'chrome'
  | 'dawn';

export interface BeamsLook {
  color: string;
  beamWidth: number;
  rotation: number;
  waveLength: number;
  depth: number;
  sharpness: number;
  twist: number;
  fillLight: number;
  glow: number;
}

export interface BeamsEngine {
  resize: () => void;
  refresh: () => void;
  setVisible: (visible: boolean) => void;
  visibilityChange: () => void;
  pointerMove: (event: PointerEvent) => void;
  pointerOut: (event: PointerEvent) => void;
  destroy: () => void;
}
